		lines = {
			{ "^Meilenstein%. Deine Fallen halten fest, was sie treffen: Jeder Treffer einer Falle hat eine Chance von ([%-%d%.,]+%%?)%%, den Feind 2 Sek%. lang festzuwurzeln%.$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^Meilenstein%. Deine kritischen Treffer haben eine Chance von ([%-%d%.,]+%%?)%%, einen kostenlosen Exorzismus zu schleudern, höchstens einmal pro Sekunde%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Meilenstein%. Du beginnst jeden Lauf mit Heiligem Schock, und jedes seiner Geschosse springt auf 2 weitere Feinde für ([%-%d%.,]+%%?)%% davon über%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Du verursachst ([%-%d%.,]+%%?)%% mehr Schaden an Feinden, die unter deinen Effekten für Schaden über Zeit leiden, etwa Verwunden und Tiefe Wunden%.$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^Die Angriffe deiner Dämonen haben eine Chance von ([%-%d%.,]+%%?)%%, ein Echo mit vollem Schaden auszulösen%. Das ist ihre einzige Echo%-Quelle%.$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^Meilenstein%. Kritische Treffer von Göttliche Pein und Heiliges Feuer setzen ihr Ziel in Brand, für ([%-%d%.,]+%%?)%% des Treffers über 6 Sek%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Absorbiert die nächsten ([%-%d%.,]+%%?) Schaden, die du erleidest, ([%-%d%.,]+%%?)%% deiner max%. Gesundheit%. Wird erneut gewirkt, sobald der Schild bricht%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Meilenstein%. Jede Heilung, die du wirkst, trifft zudem jeden Feind im Umkreis von 12 m für ([%-%d%.,]+%%?)%% der Heilung als Naturschaden%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Todesmantel verursacht sofort ([%-%d%.,]+%%?)%% des verbleibenden Schadens deines Blutsaugers auf dessen Ziel, ohne ihn zu verbrauchen%.$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^Deine kritischen Treffer mit Heiligzaubern heilen dich um ([%-%d%.,]+%%?)%% deiner maximalen Gesundheit, höchstens einmal pro Sekunde%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Meilenstein%. Frostblitz zersplittert beim Aufprall: ([%-%d%.,]+%%?)%% seines Schadens an jeden Feind im Umkreis von 5 m um sein Ziel%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Deine Zauber für Schaden über Zeit ticken ([%-%d%.,]+%%?)%% schneller: mehr Ticks und mehr Schaden in derselben Zeit%. Höchstens ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Meilenstein%. Automatischer Schuss durchdringt: Jeder Pfeil trifft zudem 1 Feind hinter seinem Ziel für ([%-%d%.,]+%%?)%% davon%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Deine Helden der Klasse (.-) erhalten ([%-%d%.,]+%%?) Talenterfahrung: 1 neuer Talentpunkt! Verteile ihn in der Waffenkammer%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Deine Helden der Klasse (.-) erhalten ([%-%d%.,]+%%?) Talenterfahrung: ([%-%d%.,]+%%?) neue Talentpunkte! Verteile sie in der Waffenkammer%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Meilenstein%. Deine kritischen Treffer mit Feuerzaubern entzünden das Ziel für ([%-%d%.,]+%%?)%% des Treffers über 4 Sek%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Ein kritischer Treffer versetzt dich in einen Schlaghagel: Abklingzeiten laden 5 Sek%. lang ([%-%d%.,]+%%?)%% schneller%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Macht dich ([%-%d%.,]+%%?) Sek%. lang immun gegen jeglichen Schaden%. Wird gewirkt, wenn du unter 35%% Gesundheit fällst%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Meilenstein%. Blitzschlag und Kettenblitzschlag haben eine Chance von ([%-%d%.,]+%%?)%%, kostenlos erneut zuzuschlagen%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^Wenn ein Feind dich im Nahkampf trifft, besteht eine Chance von ([%-%d%.,]+%%?)%%, kostenlose Wucherwurzeln zu wirken%.$", "When an enemy strikes you in melee, {v}% chance to cast a free Entangling Roots.", { "v" } },
			{ "^Schadensverringerung über der Obergrenze geht nicht verloren: Jedes 1%% davon wird zu ([%-%d%.,]+%%?)%% mehr Schaden%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Schlachtruf und deine anderen Stärkungseffekte für Schaden, Hast, Schild und Dornen sind ([%-%d%.,]+%%?)%% stärker%.$", "Battle Shout and your other damage, haste, shield and thorns buffs are {v}% stronger.", { "v" } },
			{ "^Meilenstein%. Deine kritischen Treffer reißen das Ziel auf: Es blutet für ([%-%d%.,]+%%?)%% des Treffers über 6 Sek%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Du verursachst ([%-%d%.,]+%%?)%% mehr Schaden an betäubten, festgewurzelten, verlangsamten oder fliehenden Feinden%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Vorherrschaft: Alle 12 Sek%. verstärken deine großen Dämonen ihren nächsten Angriff um %+([%-%d%.,]+%%?)%% Schaden%.$", "Supremacy: every 12 sec, your greater demons empower their next attack for +{v}% damage.", { "v" } },
			{ "^Du verursachst ([%-%d%.,]+%%?)%% mehr Schaden an eingefrorenen, betäubten, verlangsamten oder fliehenden Feinden%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^Ein gebrochener Schild zerbirst für ([%-%d%.,]+%%?) dessen, was er absorbiert hat, auf Feinde im Umkreis von ([%-%d%.,]+%%?) m$", "A broken shield bursts for {frac} of what it absorbed on enemies within {radius} yd", { "frac", "radius" } },
			{ "^Meilenstein%. Deine Schattenzauber treffen ihr Ziel zusätzlich für ([%-%d%.,]+%%?)%% seiner maximalen Gesundheit%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^Heilt dich um ([%-%d%.,]+%%?), ([%-%d%.,]+%%?)%% deiner max%. Gesundheit, ([%-%d%.,]+%%?)%. Wird gewirkt, wenn du unter 85%% Gesundheit fällst%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "amount", "share", "over" } },
			{ "^Erhöht jeglichen Schaden, den du verursachst, um ([%-%d%.,]+%%?)%% pro 10%% Schadensverringerung, die du hast%.$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^Meilenstein%. Deine kritischen Treffer lassen das Ziel über 6 Sek%. für ([%-%d%.,]+%%?)%% des Treffers bluten%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Von Demoralisierendem Ruf getroffene Feinde erleiden 6 Sek%. lang ([%-%d%.,]+%%?)%% mehr Schaden durch dich%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Totem der glühenden Magma reicht ([%-%d%.,]+%%?)%% weiter, und Totem der Verbrennung feuert auf mehr Ziele%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^Vorherrschaft: Deine Verdammniswache verursacht ([%-%d%.,]+%%?)%% mehr Schaden an Bossen und Elitegegnern%.$", "Supremacy: your Doomguard deals {v}% more damage to bosses and elites.", { "v" } },
			{ "^Seine Abklingzeit beginnt, wenn die Immunität endet: ([%-%d%.,]+%%?) Sek%. von einem Wirken zum nächsten%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Holt dich mit halber Gesundheit ins Leben zurück, wenn du stirbst%. Hält höchstens ([%-%d%.,]+%%?) Leben%.$", "Returns you to life at half health when you die. Holds {n} lives at most.", { "n" } },
			{ "^Die Abklingzeiten von Totem der Verbrennung und Totem der glühenden Magma sind ([%-%d%.,]+%%?)%% kürzer%.$", "Searing and Magma Totem cooldowns are {v}% shorter.", { "v" } },
			{ "^Ein tödlicher Hieb lässt dich stattdessen mit ([%-%d%.,]+%%?) Gesundheit zurück, einmal alle ([%-%d%.,]+%%?) Sek%.$", "A killing blow leaves you at {heal} health instead, once every {cd} sec", { "heal", "cd" } },
			{ "^Feuernova, Totem der glühenden Magma und Flammenschock verursachen ([%-%d%.,]+%%?)%% mehr Schaden%.$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^Jeder Zauber, den du wirkst, verursacht zusätzlich ([%-%d%.,]+%%?)%% deiner maximalen Gesundheit%.$", "Every spell you cast deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Deine Schattenzauber haben eine Chance von ([%-%d%.,]+%%?)%%, ihr Ziel 1,5 Sek%. lang zu betäuben%.$", "Your Shadow spells have a {v}% chance to stun what they hit for 1.5 sec.", { "v" } },
			{ "^In deiner Weihe brennende Feinde erleiden 3 Sek%. lang ([%-%d%.,]+%%?)%% mehr Schaden durch dich%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Schützt dich gegen ([%-%d%.,]+%%?) Schaden für jeden getroffenen Feind, bis zu ([%-%d%.,]+%%?), bis er bricht%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^Die Abklingzeiten von Erschütternder Schuss und Gezielter Schuss sind ([%-%d%.,]+%%?)%% kürzer%.$", "Concussive Shot and Aimed Shot cooldowns are {v}% shorter.", { "v" } },
			{ "^Jedes 1%% Schadensverringerung über der Obergrenze erhöht deinen Schaden um ([%-%d%.,]+%%?)%%%.$", "Each 1% of damage reduction past the cap increases your damage by {v}%.", { "v" } },
			{ "^Hammer der Gerechtigkeit verursacht zusätzlich ([%-%d%.,]+%%?)%% deiner maximalen Gesundheit%.$", "Hammer of Justice deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Erhöht jeglichen Schaden und die kritische Trefferchance deiner Dämonen um ([%-%d%.,]+%%?)%%%.$", "Increases all damage and your demons' critical strike chance by {v}%.", { "v" } },
			{ "^Vorherrschaft: Das Höllenfeuer deiner Höllenbestie verursacht ([%-%d%.,]+%%?)%% mehr Schaden%.$", "Supremacy: your Infernal's Hellfire deals {v}% more damage.", { "v" } },
			{ "^Du hast ([%-%d%.,]+%%?)%% Schaden, ([%-%d%.,]+%%?) maximale Gesundheit und ([%-%d%.,]+%%?) Gesundheit pro Sekunde erhalten%.$", "You have gained {damage}% damage, {health} maximum health and {regen} health per second.", { "damage", "health", "regen" } },
			{ "^Deine Feuerzauber haben eine Chance von ([%-%d%.,]+%%?)%%, ihr Ziel 1 Sek%. lang zu betäuben%.$", "Your Fire spells have a {v}% chance to stun what they hit for 1 sec.", { "v" } },
			{ "^([%-%d%.,]+%%?)%% des Nahkampfschadens, den Feinde dir zufügen, wird auf sie zurückgeworfen%.$", "{v}% of the damage enemies deal you in melee is dealt back to them.", { "v" } },
			{ "^Erhöht jeglichen Schaden, den du verursachst, um ([%-%d%.,]+%%?), solange ein Schild hält%.$", "Increases all damage you deal by {p} while a shield holds.", { "p" } },
			{ "^Deine Zauber für Schaden über Zeit stapeln sich jetzt ([%-%d%.,]+%%?)%-mal auf einem Feind%.$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^Deine Stärkungseffekte für Schaden, Hast, Schild und Dornen sind ([%-%d%.,]+%%?) stärker%.$", "Your damage, haste, shield and thorns buffs are {p} stronger.", { "p" } },
			{ "^Feinde, die mit (.-) auf sich sterben, explodieren für ([%-%d%.,]+%%?) ihrer max%. Gesundheit$", "Enemies that die with {spell} on them explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Jeder Tick von Weihe verursacht zusätzlich ([%-%d%.,]+%%?)%% deiner maximalen Gesundheit%.$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Gibt den Angriffen deiner Dämonen eine Chance von ([%-%d%.,]+%%?), erneut zuzuschlagen%.$", "Gives your demons' attacks a {p} chance to strike again.", { "p" } },
			{ "^Du verursachst ([%-%d%.,]+%%?)%% mehr Schaden pro 10%% Schadensverringerung, die du hast%.$", "You deal {v}% more damage for every 10% damage reduction you have.", { "v" } },
			{ "^Feinde, die du während (.-) tötest, explodieren für ([%-%d%.,]+%%?) ihrer max%. Gesundheit$", "Enemies you kill during {spell} explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Hammer der Gerechtigkeit verursacht ([%-%d%.,]+%%?)%% mehr Schaden und lädt schneller%.$", "Hammer of Justice deals {v}% more damage and recovers faster.", { "v" } },
