		lines = {
			{ "^Hito%. Tus trampas retienen lo que alcanzan: cada golpe de una trampa tiene un ([%-%d%.,]+%%?)%% de probabilidad de enraizar al enemigo durante 2 s%.$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^Infliges un ([%-%d%.,]+%%?)%% más de daño a los enemigos afectados por tus efectos de daño en el tiempo, como Desgarrar y Heridas profundas%.$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^Tus hechizos de daño en el tiempo pulsan un ([%-%d%.,]+%%?)%% más rápido: más pulsos, y más daño, en el mismo tiempo%. Como máximo un ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Hito%. Tus golpes críticos tienen un ([%-%d%.,]+%%?)%% de probabilidad de lanzar un Exorcismo gratuito, como mucho una vez por segundo%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Hito%. Disparo automático perfora: cada flecha golpea también a 1 enemigo más allá de su objetivo con un ([%-%d%.,]+%%?)%% de su daño%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Espiral de la muerte inflige al instante un ([%-%d%.,]+%%?)%% del daño restante de tu Drenar vida sobre su objetivo, sin consumirlo%.$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^Hito%. Cada sanación que lanzas golpea también a todo enemigo a 12 m con un ([%-%d%.,]+%%?)%% de la sanación como daño de Naturaleza%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Hito%. Empiezas cada partida con Choque Sagrado, y cada uno de sus rayos salta a 2 enemigos más con un ([%-%d%.,]+%%?)%% de su daño%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Absorbe los próximos ([%-%d%.,]+%%?) de daño que recibas, el ([%-%d%.,]+%%?)%% de tu salud máxima%. Se vuelve a lanzar cuando se rompe el escudo%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Hito%. Los golpes críticos de Punición y Fuego Sagrado prenden fuego a su objetivo por un ([%-%d%.,]+%%?)%% del golpe durante 6 s%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Los ataques de tus demonios tienen un ([%-%d%.,]+%%?)%% de probabilidad de hacer Eco con todo su daño%. Es su única fuente de Eco%.$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^Un golpe crítico te lanza en ráfaga: los tiempos de reutilización se recuperan un ([%-%d%.,]+%%?)%% más rápido durante 5 s%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Hito%. Descarga de relámpagos y Cadena de relámpagos tienen un ([%-%d%.,]+%%?)%% de probabilidad de golpear otra vez gratis%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^Cuando un enemigo te golpea cuerpo a cuerpo, ([%-%d%.,]+%%?)%% de probabilidad de lanzar unas Raíces enredadoras gratuitas%.$", "When an enemy strikes you in melee, {v}% chance to cast a free Entangling Roots.", { "v" } },
			{ "^Tus héroes de clase (.-) ganan ([%-%d%.,]+%%?) de experiencia de talentos: ¡([%-%d%.,]+%%?) puntos de talento nuevos! Gástalos en la armería%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Tus héroes de clase (.-) ganan ([%-%d%.,]+%%?) de experiencia de talentos: ¡1 punto de talento nuevo! Gástalo en la armería%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Hito%. Descarga de Escarcha se astilla al impactar: un ([%-%d%.,]+%%?)%% de su daño a todo enemigo a 5 m de su objetivo%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Grito de batalla y tus demás beneficios de daño, celeridad, escudo y espinas son un ([%-%d%.,]+%%?)%% más potentes%.$", "Battle Shout and your other damage, haste, shield and thorns buffs are {v}% stronger.", { "v" } },
			{ "^La reducción de daño por encima del límite no se pierde: cada 1%% se convierte en un ([%-%d%.,]+%%?)%% más de daño%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Su tiempo de reutilización empieza cuando termina la inmunidad: ([%-%d%.,]+%%?) s de un lanzamiento al siguiente%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Los tiempos de reutilización de Disparo de conmoción y Disparo de puntería son un ([%-%d%.,]+%%?)%% más cortos%.$", "Concussive Shot and Aimed Shot cooldowns are {v}% shorter.", { "v" } },
			{ "^Tus golpes críticos Sagrados te sanan un ([%-%d%.,]+%%?)%% de tu salud máxima, como mucho una vez por segundo%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Tus hechizos de Sombras tienen un ([%-%d%.,]+%%?)%% de probabilidad de aturdir lo que alcanzan durante 1,5 s%.$", "Your Shadow spells have a {v}% chance to stun what they hit for 1.5 sec.", { "v" } },
			{ "^Los enemigos alcanzados por Grito desmoralizador reciben un ([%-%d%.,]+%%?)%% más de daño de ti durante 6 s%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Hito%. Tus hechizos de Sombras también golpean a lo que alcanzan por el ([%-%d%.,]+%%?)%% de su salud máxima%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^Supremacía: cada 12 s, tus demonios mayores potencian su siguiente ataque con un %+([%-%d%.,]+%%?)%% de daño%.$", "Supremacy: every 12 sec, your greater demons empower their next attack for +{v}% damage.", { "v" } },
			{ "^Tus hechizos de Fuego tienen un ([%-%d%.,]+%%?)%% de probabilidad de aturdir lo que alcanzan durante 1 s%.$", "Your Fire spells have a {v}% chance to stun what they hit for 1 sec.", { "v" } },
			{ "^Hito%. Tus golpes críticos abren en canal al objetivo: sangra un ([%-%d%.,]+%%?)%% del golpe durante 6 s%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Los tiempos de reutilización de Espiral de la muerte y Drenar vida son un ([%-%d%.,]+%%?)%% más cortos%.$", "Death Coil and Drain Life cooldowns are {v}% shorter.", { "v" } },
			{ "^Un escudo roto estalla con un ([%-%d%.,]+%%?) de lo que absorbió sobre los enemigos en un radio de ([%-%d%.,]+%%?) m$", "A broken shield bursts for {frac} of what it absorbed on enemies within {radius} yd", { "frac", "radius" } },
			{ "^Hito%. Tus golpes críticos de Fuego prenden al objetivo por un ([%-%d%.,]+%%?)%% del golpe durante 4 s%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Los tiempos de reutilización de Descarga de las Sombras e Inmolar son un ([%-%d%.,]+%%?)%% más cortos%.$", "Shadow Bolt and Immolate cooldowns are {v}% shorter.", { "v" } },
			{ "^Los enemigos que arden en tu Consagración reciben un ([%-%d%.,]+%%?)%% más de daño de ti durante 3 s%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Te devuelve a la vida con la mitad de salud cuando mueres%. Guarda ([%-%d%.,]+%%?) vidas como máximo%.$", "Returns you to life at half health when you die. Holds {n} lives at most.", { "n" } },
