			{ "^Infliges un ([%-%d%.,]+%%?)%% más de daño a enemigos congelados, aturdidos, ralentizados o que huyen%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^Infliges un ([%-%d%.,]+%%?)%% más de daño a enemigos aturdidos, enraizados, ralentizados o que huyen%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Aumenta todo el daño que infliges un ([%-%d%.,]+%%?)%% por cada 10%% de reducción de daño que tengas%.$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^Los tiempos de reutilización de Ola explosiva y Piroexplosión son un ([%-%d%.,]+%%?)%% más cortos%.$", "Blast Wave and Pyroblast cooldowns are {v}% shorter.", { "v" } },
