		lines = {
			{ "^「デスコイル」が、標的にかかった「ドレインライフ」の残りダメージの([%-%d%.,]+%%?)%%を即座に与えます。「ドレインライフ」は消費されません。$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^節目。「スマイト」と「ホーリーファイア」のクリティカルが標的を燃やし、6秒かけて一撃の([%-%d%.,]+%%?)%%のダメージを与えます。$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^節目。毎回「ホーリーショック」を持ってランを始め、その光弾はさらに2体の敵へ跳ね、([%-%d%.,]+%%?)%%のダメージを与えます。$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^節目。「フロストボルト」が命中時に砕け、標的から5ヤード以内のすべての敵にそのダメージの([%-%d%.,]+%%?)%%を与えます。$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^「レンド」や「深い傷」など、あなたの継続ダメージ効果を受けている敵に与えるダメージが([%-%d%.,]+%%?)%%増加します。$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^継続ダメージ呪文の間隔が([%-%d%.,]+%%?)%%速くなります：同じ時間でより多く、より多くのダメージを与えます。最大([%-%d%.,]+%%?)%%。$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^節目。「オートショット」が貫通：すべての矢が標的の奥にいる敵1体にもその([%-%d%.,]+%%?)%%のダメージを与えます。$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^節目。唱えたすべての回復呪文が、12ヤード以内のすべての敵に回復量の([%-%d%.,]+%%?)%%の自然ダメージも与えます。$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^あなたの「コンセクレーション」で焼かれる敵は、3秒間あなたから受けるダメージが([%-%d%.,]+%%?)%%増加します。$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^上限を超えた被ダメージ軽減も無駄になりません：その1%%ごとに与えるダメージが([%-%d%.,]+%%?)%%増加します。$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^「バトルシャウト」をはじめ、ダメージ、ヘイスト、シールド、ソーンのバフが([%-%d%.,]+%%?)%%強くなります。$", "Battle Shout and your other damage, haste, shield and thorns buffs are {v}% stronger.", { "v" } },
			{ "^節目。罠が命中した敵を捕らえる：罠が命中するたびに([%-%d%.,]+%%?)%%の確率で敵を2秒間その場に縛ります。$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^節目。「ライトニングボルト」と「チェインライトニング」が([%-%d%.,]+%%?)%%の確率で無料で再び撃ちます。$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^次に受ける([%-%d%.,]+%%?)のダメージ（最大体力の([%-%d%.,]+%%?)%%）を吸収します。シールドが砕けると再び唱えます。$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^「ファイアノヴァ」「マグマトーテム」「フレイムショック」のダメージが([%-%d%.,]+%%?)%%増加します。$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^「マグマトーテム」の範囲が([%-%d%.,]+%%?)%%広がり、「灼熱のトーテム」がより多くの標的を撃ちます。$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^節目。クリティカルが([%-%d%.,]+%%?)%%の確率で無料の「エクソシズム」を放ちます（最大で毎秒1回）。$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^悪魔の攻撃が([%-%d%.,]+%%?)%%の確率で全ダメージの残響を起こします。これが悪魔の唯一の残響源です。$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^節目。クリティカルが標的を引き裂く：6秒かけて一撃の([%-%d%.,]+%%?)%%の出血ダメージを与えます。$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^「コンカッシブショット」と「エイムドショット」のクールダウンが([%-%d%.,]+%%?)%%短くなります。$", "Concussive Shot and Aimed Shot cooldowns are {v}% shorter.", { "v" } },
			{ "^「士気を挫く叫び」を受けた敵は、6秒間あなたから受けるダメージが([%-%d%.,]+%%?)%%増加します。$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^節目。火のクリティカルが標的に着火し、4秒かけて一撃の([%-%d%.,]+%%?)%%のダメージを与えます。$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^クリティカルで連撃状態になります：5秒間クールダウンの回復が([%-%d%.,]+%%?)%%速くなります。$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^節目。クリティカルが標的を出血させ、6秒かけて一撃の([%-%d%.,]+%%?)%%のダメージを与えます。$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
