		lines = {
			{ "^죽음의 고리가 대상에게 걸린 생명력 흡수의 남은 피해의 ([%-%d%.,]+%%?)%%를 즉시 줍니다%. 생명력 흡수는 소모되지 않습니다%.$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^이정표%. 성스러운 일격과 신성한 불꽃의 치명타가 대상을 불태워 6초에 걸쳐 그 공격의 ([%-%d%.,]+%%?)%%만큼 피해를 줍니다%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^이정표%. 모든 도전을 신성 충격을 가지고 시작하며, 각 빛줄기가 적 2명에게 더 튀어 ([%-%d%.,]+%%?)%%의 효과를 줍니다%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^이정표%. 얼음 화살이 충돌하며 쪼개집니다: 대상 주위 5미터 내의 모든 적에게 피해의 ([%-%d%.,]+%%?)%%를 줍니다%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^악마의 공격이 ([%-%d%.,]+%%?)%% 확률로 전체 피해의 메아리를 일으킵니다%. 이것이 악마의 유일한 메아리 원천입니다%.$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^지속 피해 주문이 ([%-%d%.,]+%%?)%% 빨리 피해를 줍니다: 같은 시간에 더 많은 횟수와 더 많은 피해%. 최대 ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^이정표%. 시전하는 모든 치유가 12미터 내의 모든 적에게도 치유량의 ([%-%d%.,]+%%?)%%만큼 자연 피해를 줍니다%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^다음에 받는 피해 ([%-%d%.,]+%%?)%(최대 생명력의 ([%-%d%.,]+%%?)%%%)을%(를%) 흡수합니다%. 보호막이 깨지면 다시 시전합니다%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^이정표%. 덫이 적중한 적을 붙잡습니다: 덫이 적중할 때마다 ([%-%d%.,]+%%?)%% 확률로 적을 2초간 묶습니다%.$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^이정표%. 자동 사격이 관통합니다: 화살마다 대상 너머의 적 1명에게도 ([%-%d%.,]+%%?)%%의 효과를 줍니다%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^이정표%. 암흑 주문이 적중한 대상에게 그 대상의 최대 생명력 ([%-%d%.,]+%%?)%%만큼 추가 피해를 줍니다%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^이정표%. 치명타가 대상에게 출혈을 일으켜 6초에 걸쳐 그 공격의 ([%-%d%.,]+%%?)%%만큼 피해를 줍니다%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^분쇄나 깊은 상처 등 당신의 지속 피해 효과에 걸린 적에게 주는 피해가 ([%-%d%.,]+%%?)%% 증가합니다%.$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
