		lines = {
			{ "^Kamień milowy%. Każdą wyprawę zaczynasz ze Świętym Wstrząsem, a każdy jego pocisk przeskakuje na 2 kolejnych wrogów za ([%-%d%.,]+%%?)%% siły%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Kamień milowy%. Lodowy Pocisk rozpryskuje się przy uderzeniu: ([%-%d%.,]+%%?)%% jego obrażeń trafia każdego wroga w promieniu 5 jd od celu%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Kamień milowy%. Twoje pułapki trzymają to, co trafią: każde trafienie pułapki ma ([%-%d%.,]+%%?)%% szansy, by unieruchomić wroga na 2 s%.$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^Kamień milowy%. Każde rzucone leczenie uderza też każdego wroga w promieniu 12 jd za ([%-%d%.,]+%%?)%% leczenia jako obrażenia natury%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Zadajesz o ([%-%d%.,]+%%?)%% więcej obrażeń wrogom pod wpływem twoich efektów obrażeń w czasie, takich jak Rozdarcie i Głębokie Rany%.$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^Twoje zaklęcia obrażeń w czasie tykają ([%-%d%.,]+%%?)%% szybciej: więcej tyknięć i więcej obrażeń w tym samym czasie%. Najwyżej ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Kamień milowy%. Twoje trafienia krytyczne mają ([%-%d%.,]+%%?)%% szansy, by ciskać darmowym Egzorcyzmem, najwyżej raz na sekundę%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Twoje krytyczne trafienia zaklęciami światłości leczą cię o ([%-%d%.,]+%%?)%% maksymalnego zdrowia, najwyżej raz na sekundę%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Zwój Śmierci natychmiast zadaje ([%-%d%.,]+%%?)%% pozostałych obrażeń twojego Wyssania Życia na celu, nie zużywając go%.$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^Pochłania następne ([%-%d%.,]+%%?) otrzymanych obrażeń, ([%-%d%.,]+%%?)%% maksymalnego zdrowia%. Rzucane ponownie, gdy tarcza pęknie%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Kamień milowy%. Krytyczne trafienia Porażenia i Świętego Ognia podpalają cel za ([%-%d%.,]+%%?)%% trafienia przez 6 s%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Okrzyk Bojowy i twoje pozostałe wzmocnienia obrażeń, pośpiechu, tarczy i cierni są o ([%-%d%.,]+%%?)%% silniejsze%.$", "Battle Shout and your other damage, haste, shield and thorns buffs are {v}% stronger.", { "v" } },
			{ "^Kamień milowy%. Automatyczny Strzał przebija: każda strzała trafia też 1 wroga za celem za ([%-%d%.,]+%%?)%% siły%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Kamień milowy%. Twoje zaklęcia cienia uderzają też trafiony cel za ([%-%d%.,]+%%?)%% jego maksymalnego zdrowia%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^Wrogowie trafieni Demoralizującym Okrzykiem otrzymują od ciebie ([%-%d%.,]+%%?)%% więcej obrażeń przez 6 s%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Kamień milowy%. Twoje trafienia krytyczne sprawiają, że cel krwawi przez 6 s za ([%-%d%.,]+%%?)%% trafienia%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Zadajesz ([%-%d%.,]+%%?)%% więcej obrażeń ogłuszonym, unieruchomionym, spowolnionym lub uciekającym wrogom%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Kamień milowy%. Błyskawica i Łańcuch Błyskawic mają ([%-%d%.,]+%%?)%% szansy, by uderzyć ponownie za darmo%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^Kamień milowy%. Twoje trafienia krytyczne rozdzierają cel: krwawi przez 6 s za ([%-%d%.,]+%%?)%% trafienia%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Ataki twoich demonów mają ([%-%d%.,]+%%?)%% szansy na Echo za pełne obrażenia%. To ich jedyne źródło Echa%.$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^Redukcja obrażeń ponad limit się nie marnuje: każdy 1%% zamienia się w ([%-%d%.,]+%%?)%% więcej obrażeń%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Daje odporność na wszelkie obrażenia na ([%-%d%.,]+%%?) s%. Rzucane, gdy spadniesz poniżej 35%% zdrowia%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Kamień milowy%. Twoje krytyczne trafienia ogniem podpalają cel za ([%-%d%.,]+%%?)%% trafienia przez 4 s%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Osłania cię przed ([%-%d%.,]+%%?) obrażeń za każdego trafionego wroga, do ([%-%d%.,]+%%?), dopóki tarcza nie pęknie%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^Zadajesz ([%-%d%.,]+%%?)%% więcej obrażeń zamrożonym, ogłuszonym, spowolnionym lub uciekającym wrogom%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^Trafienie krytyczne wprawia cię w szał: czasy odnowienia mijają ([%-%d%.,]+%%?)%% szybciej przez 5 s%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Klasa (.-) zdobywa ([%-%d%.,]+%%?) doświadczenia talentów: nowe punkty talentów: ([%-%d%.,]+%%?)! Wydaj je w zbrojowni%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Supremacja: co 12 s twoje większe demony wzmacniają swój następny atak o %+([%-%d%.,]+%%?)%% obrażeń%.$", "Supremacy: every 12 sec, your greater demons empower their next attack for +{v}% damage.", { "v" } },
			{ "^Wrogowie płonący w twoim Uświęceniu otrzymują od ciebie ([%-%d%.,]+%%?)%% więcej obrażeń przez 3 s%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Leczy cię o ([%-%d%.,]+%%?), ([%-%d%.,]+%%?)%% maksymalnego zdrowia, ([%-%d%.,]+%%?)%. Rzucane, gdy spadniesz poniżej 85%% zdrowia%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "amount", "share", "over" } },
			{ "^Gdy wróg uderza cię w zwarciu, ([%-%d%.,]+%%?)%% szansy na rzucenie darmowych Splątujących Korzeni%.$", "When an enemy strikes you in melee, {v}% chance to cast a free Entangling Roots.", { "v" } },
			{ "^Klasa (.-) zdobywa ([%-%d%.,]+%%?) doświadczenia talentów: 1 nowy punkt talentu! Wydaj go w zbrojowni%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Zwiększa wszystkie zadawane obrażenia o ([%-%d%.,]+%%?)%% za każde posiadane 10%% redukcji obrażeń%.$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^Zwiększa wszystkie obrażenia i szansę twoich demonów na trafienie krytyczne o ([%-%d%.,]+%%?)%%%.$", "Increases all damage and your demons' critical strike chance by {v}%.", { "v" } },
			{ "^Przywraca cię do życia z połową zdrowia, gdy zginiesz%. Mieści najwyżej ([%-%d%.,]+%%?) życia%.$", "Returns you to life at half health when you die. Holds {n} lives at most.", { "n" } },
			{ "^Pęknięta tarcza wybucha za ([%-%d%.,]+%%?) tego, co pochłonęła, na wrogów w promieniu ([%-%d%.,]+%%?) jd$", "A broken shield bursts for {frac} of what it absorbed on enemies within {radius} yd", { "frac", "radius" } },
			{ "^Supremacja: twój Strażnik Zagłady zadaje ([%-%d%.,]+%%?)%% więcej obrażeń bossom i elitom%.$", "Supremacy: your Doomguard deals {v}% more damage to bosses and elites.", { "v" } },
			{ "^Totem Magmy sięga ([%-%d%.,]+%%?)%% dalej, a Totem Żaru strzela do większej liczby celów%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^Osłona z Uderzenia Tarczą mieści o ([%-%d%.,]+%%?)%% twojego maksymalnego zdrowia więcej%.$", "Shield Slam's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^Twoje zaklęcia obrażeń w czasie kumulują się teraz ([%-%d%.,]+%%?) razy na jednym wrogu%.$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^Czasy odnowienia Ogłuszającego Strzału i Celnego Strzału są krótsze o ([%-%d%.,]+%%?)%%%.$", "Concussive Shot and Aimed Shot cooldowns are {v}% shorter.", { "v" } },
			{ "^Supremacja: Piekielny Ogień twojego Piekielnika zadaje ([%-%d%.,]+%%?)%% więcej obrażeń%.$", "Supremacy: your Infernal's Hellfire deals {v}% more damage.", { "v" } },
			{ "^Wrogowie, którzy giną pod wpływem (.-), wybuchają za ([%-%d%.,]+%%?) swojego maks%. zdrowia$", "Enemies that die with {spell} on them explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Każde rzucone zaklęcie zadaje dodatkowo ([%-%d%.,]+%%?)%% twojego maksymalnego zdrowia%.$", "Every spell you cast deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Twoje wzmocnienia obrażeń, pośpiechu, tarczy i cierni są silniejsze o ([%-%d%.,]+%%?)%.$", "Your damage, haste, shield and thorns buffs are {p} stronger.", { "p" } },
			{ "^Każdy takt Uświęcenia zadaje dodatkowo ([%-%d%.,]+%%?)%% twojego maksymalnego zdrowia%.$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Ognista Nowa, Totem Magmy i Wstrząs Płomieni zadają ([%-%d%.,]+%%?)%% więcej obrażeń%.$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^Młot Sprawiedliwości zadaje dodatkowo ([%-%d%.,]+%%?)%% twojego maksymalnego zdrowia%.$", "Hammer of Justice deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Młot Sprawiedliwości zadaje ([%-%d%.,]+%%?)%% więcej obrażeń i szybciej się odnawia%.$", "Hammer of Justice deals {v}% more damage and recovers faster.", { "v" } },
			{ "^Czas odnowienia liczy się od końca odporności: ([%-%d%.,]+%%?) s między rzuceniami%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Zadajesz ([%-%d%.,]+%%?)%% więcej obrażeń za każde 10%% redukcji obrażeń, które masz%.$", "You deal {v}% more damage for every 10% damage reduction you have.", { "v" } },
			{ "^Osłona z Uświęcenia mieści o ([%-%d%.,]+%%?)%% twojego maksymalnego zdrowia więcej%.$", "Consecration's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^Każdy 1%% redukcji obrażeń ponad limit zwiększa twoje obrażenia o ([%-%d%.,]+%%?)%%%.$", "Each 1% of damage reduction past the cap increases your damage by {v}%.", { "v" } },
			{ "^Zwiększa szansę na trafienie krytyczne twoją i twoich zwierząt o ([%-%d%.,]+%%?)%%%.$", "Increases your and your pets' critical strike chance by {v}%.", { "v" } },
			{ "^Twoje efekty obrażeń rozłożonych w czasie zadają ([%-%d%.,]+%%?)%% więcej obrażeń%.$", "Your damage-over-time effects deal {v}% more damage.", { "v" } },
			{ "^Zwiększa wszystkie obrażenia i szansę na trafienie krytyczne o ([%-%d%.,]+%%?)%%%.$", "Increases all damage and your critical strike chance by {v}%.", { "v" } },
			{ "^Uderzenie Tarczą zadaje dodatkowo ([%-%d%.,]+%%?)%% twojego maksymalnego zdrowia%.$", "Shield Slam deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Zyskujesz ([%-%d%.,]+%%?)%% obrażeń, ([%-%d%.,]+%%?) maksymalnego zdrowia i ([%-%d%.,]+%%?) zdrowia na sekundę%.$", "You have gained {damage}% damage, {health} maximum health and {regen} health per second.", { "damage", "health", "regen" } },
			{ "^Czasy odnowienia Fali Uderzeniowej i Pirowybuchu są krótsze o ([%-%d%.,]+%%?)%%%.$", "Blast Wave and Pyroblast cooldowns are {v}% shorter.", { "v" } },
			{ "^Zabici przez ciebie wrogowie wybuchają za ([%-%d%.,]+%%?) swojego maks%. zdrowia$", "Enemies you kill explode for {frac} of their max health", { "frac" } },
			{ "^Uderzenie Tarczą zadaje ([%-%d%.,]+%%?)%% więcej obrażeń i szybciej się odnawia%.$", "Shield Slam deals {v}% more damage and recovers faster.", { "v" } },
			{ "^Śmiertelny cios zostawia cię zamiast tego z ([%-%d%.,]+%%?) zdrowia, raz na ([%-%d%.,]+%%?) s$", "A killing blow leaves you at {heal} health instead, once every {cd} sec", { "heal", "cd" } },
			{ "^Czasy odnowienia Zwoju Śmierci i Wyssania Życia są krótsze o ([%-%d%.,]+%%?)%%%.$", "Death Coil and Drain Life cooldowns are {v}% shorter.", { "v" } },
			{ "^Przez ([%-%d%.,]+%%?) s wrogowie, którzy trafią cię wręcz, otrzymują ([%-%d%.,]+%%?) obrażeń%.(.-)$", "For {dur} sec, enemies that hit you in melee take {n} damage.{in_fight}", { "dur", "n", "in_fight" } },
			{ "^([%-%d%.,]+%%?) Zaczyna z: (.-); każdy poziom oferuje trzy z jej zaklęć%. ([%-%d%.,]+%%?) zdrowia%.$", "{blurb} Starts with {spell}; every level offers three of its spells. {hp} health.", { "blurb", "spell", "hp" } },
			{ "^Dotyka (.-) w promieniu ([%-%d%.,]+%%?) jd([%-%d%.,]+%%?): ([%-%d%.,]+%%?) obrażeń %((.-)%) przez ([%-%d%.,]+%%?) s, w ([%-%d%.,]+%%?) tyknięciach%.([%-%d%.,]+%%?)$", "Afflicts {targets} within {range} yd{whom}: {total} {school} damage over {secs} sec, in {ticks} ticks.{stack}", { "targets", "range", "whom", "total", "school", "secs", "ticks", "stack" } },
			{ "^Uderzenie Płomieni i Fala Uderzeniowa zadają ([%-%d%.,]+%%?)%% więcej obrażeń%.$", "Flamestrike and Blast Wave deal {v}% more damage.", { "v" } },
			{ "^Zwiększa obrażenia twojego Piekielnika i Strażnika Zagłady o ([%-%d%.,]+%%?)%.$", "Increases the damage of your Infernal and Doomguard by {p}.", { "p" } },
