			{ "^Zwiększa wszystkie zadawane obrażenia o ([%-%d%.,]+%%?), póki trzyma tarcza%.$", "Increases all damage you deal by {p} while a shield holds.", { "p" } },
			{ "^Wrogowie zabici podczas (.-) wybuchają za ([%-%d%.,]+%%?) swojego maks%. zdrowia$", "Enemies you kill during {spell} explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Czasy odnowienia Pocisku Cienia i Podpalenia są krótsze o ([%-%d%.,]+%%?)%%%.$", "Shadow Bolt and Immolate cooldowns are {v}% shorter.", { "v" } },
			{ "^Tajemne zaklęcia i zaklęcia natury zadają ([%-%d%.,]+%%?)%% więcej obrażeń%.$", "Arcane and Nature spells deal {v}% more damage.", { "v" } },
			{ "^Zwiększa obrażenia Ognistych Pocisków twoich Chochlików o ([%-%d%.,]+%%?)%.$", "Increases the damage of your Imps' Firebolts by {p}.", { "p" } },
			{ "^Czasy odnowienia Totemu Żaru i Totemu Magmy są krótsze o ([%-%d%.,]+%%?)%%%.$", "Searing and Magma Totem cooldowns are {v}% shorter.", { "v" } },
			{ "^Czasy odnowienia Porażenia i Świętego Ognia są krótsze o ([%-%d%.,]+%%?)%%%.$", "Smite and Holy Fire cooldowns are {v}% shorter.", { "v" } },
			{ "^Twoje zaklęcia ognia mają ([%-%d%.,]+%%?)%% szansy, by ogłuszyć cel na 1 s%.$", "Your Fire spells have a {v}% chance to stun what they hit for 1 sec.", { "v" } },
