		lines = {
			{ "^Вы наносите на ([%-%d%.,]+%%?)%% больше урона врагам под вашими эффектами периодического урона, такими как «Кровопускание» и «Глубокие раны»%.$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^Ваши заклинания периодического урона срабатывают на ([%-%d%.,]+%%?)%% быстрее: больше тактов и больше урона за то же время%. Не более ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Веха%. «Автоматическая стрельба» пробивает насквозь: каждая стрела также поражает 1 врага за целью на ([%-%d%.,]+%%?)%% своего урона%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Веха%. Ваши ловушки удерживают задетых: каждое срабатывание ловушки с вероятностью ([%-%d%.,]+%%?)%% обездвиживает врага на 2 сек%.$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^Веха%. Вы начинаете каждый забег с «Шоком небес», и каждый его разряд перескакивает ещё на 2 врагов с ([%-%d%.,]+%%?)%% урона%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Веха%. Каждое ваше исцеление также поражает всех врагов в радиусе 12 м на ([%-%d%.,]+%%?)%% исцеления уроном от сил природы%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^«Лик смерти» мгновенно наносит ([%-%d%.,]+%%?)%% оставшегося урона вашего «Похищения жизни» на цели, не расходуя его%.$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^Веха%. Ваши критические удары с вероятностью ([%-%d%.,]+%%?)%% бросают бесплатный «Экзорцизм», не чаще раза в секунду%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Атаки ваших демонов с вероятностью ([%-%d%.,]+%%?)%% отдаются эхом с полным уроном%. Это их единственный источник эха%.$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^Ваши герои класса «(.-)» получают ([%-%d%.,]+%%?) опыта талантов: новых очков талантов — ([%-%d%.,]+%%?)! Потратьте их в оружейной%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^Ваши герои класса «(.-)» получают ([%-%d%.,]+%%?) опыта талантов: 1 новое очко талантов! Потратьте его в оружейной%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Делает вас невосприимчивым ко всему урону на ([%-%d%.,]+%%?) сек%. Применяется, когда здоровье падает ниже 35%%%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Веха%. «Ледяная стрела» разлетается при попадании: ([%-%d%.,]+%%?)%% её урона всем врагам в радиусе 5 м от цели%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Критический удар приводит вас в шквал: время восстановления идёт на ([%-%d%.,]+%%?)%% быстрее в течение 5 сек%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Снижение урона сверх предела не пропадает: каждый 1%% превращается в ([%-%d%.,]+%%?)%% дополнительного урона%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Восстановление начинается, когда невосприимчивость заканчивается: ([%-%d%.,]+%%?) сек%. между применениями%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Веха%. Ваши критические удары заставляют цель истекать кровью на ([%-%d%.,]+%%?)%% от удара в течение 6 сек%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Когда враг бьёт вас в ближнем бою, с вероятностью ([%-%d%.,]+%%?)%% применяется бесплатный «Гнев деревьев»%.$", "When an enemy strikes you in melee, {v}% chance to cast a free Entangling Roots.", { "v" } },
			{ "^Враги, задетые «Деморализующим криком», получают от вас на ([%-%d%.,]+%%?)%% больше урона в течение 6 сек%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^«Тотем магмы» достаёт на ([%-%d%.,]+%%?)%% дальше, а «Опаляющий тотем» стреляет по большему числу целей%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^Вы наносите на ([%-%d%.,]+%%?)%% больше урона оглушённым, обездвиженным, замедленным или бегущим врагам%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Превосходство: каждые 12 сек%. ваши высшие демоны усиливают следующую атаку на %+([%-%d%.,]+%%?)%% урона%.$", "Supremacy: every 12 sec, your greater demons empower their next attack for +{v}% damage.", { "v" } },
			{ "^Вы наносите на ([%-%d%.,]+%%?)%% больше урона замороженным, оглушённым, замедленным или бегущим врагам%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
