		lines = {
			{ "^Ваші закляття періодичної шкоди діють на ([%-%d%.,]+%%?)%% частіше: більше імпульсів і більше шкоди за той самий час%. Не більше ([%-%d%.,]+%%?)%%%.$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^Віха%. Ви починаєте кожен забіг зі «Святим шоком», і кожен його розряд перескакує ще на 2 ворогів на ([%-%d%.,]+%%?)%% від нього%.$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^Ви завдаєте на ([%-%d%.,]+%%?)%% більше шкоди ворогам під дією ваших ефектів періодичної шкоди, як%-от «Розрив» і «Глибокі рани»%.$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^«Кільце смерті» миттєво завдає ([%-%d%.,]+%%?)%% залишкової шкоди вашого «Висмоктування життя» на цілі, не витрачаючи його%.$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^Віха%. Ваші критичні удари мають ([%-%d%.,]+%%?)%% шансу метнути безплатний «Екзорцизм», не частіше разу на секунду%.$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^Віха%. «Автоматичний постріл» пронизує: кожна стріла також влучає в 1 ворога за ціллю на ([%-%d%.,]+%%?)%% від неї%.$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^Віха%. Кожне ваше зцілення також б'є кожного ворога в межах 12 м на ([%-%d%.,]+%%?)%% від зцілення шкодою природи%.$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^Віха%. «Крижана стріла» розколюється при влучанні: ([%-%d%.,]+%%?)%% її шкоди кожному ворогу в межах 5 м від цілі%.$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^Робить вас невразливим до будь%-якої шкоди на ([%-%d%.,]+%%?) с%. Застосовується, коли здоров'я падає нижче 35%%%.$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^Віха%. Ваші пастки тримають те, що вразили: кожен удар пастки має ([%-%d%.,]+%%?)%% шансу сковати ворога на 2 с%.$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^Ви завдаєте на ([%-%d%.,]+%%?)%% більше шкоди замороженим, оглушеним, сповільненим ворогам або тим, хто тікає%.$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^Атаки ваших демонів мають ([%-%d%.,]+%%?)%% шансу відлунити з повною шкодою%. Це їхнє єдине джерело відлуння%.$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^Перезарядка починається, коли невразливість мине: ([%-%d%.,]+%%?) с від одного застосування до наступного%.$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^Вороги, уражені «Деморалізуючим криком», отримують від вас на ([%-%d%.,]+%%?)%% більше шкоди протягом 6 с%.$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^Віха%. Критичні удари «Кари» і «Святого вогню» підпалюють ціль на ([%-%d%.,]+%%?)%% від удару протягом 6 с%.$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Віха%. Ваші критичні удари роздирають ціль: вона стікає кров'ю на ([%-%d%.,]+%%?)%% від удару протягом 6 с%.$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Вороги, що горять у вашому «Освяченні», отримують від вас на ([%-%d%.,]+%%?)%% більше шкоди протягом 3 с%.$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^Ви завдаєте на ([%-%d%.,]+%%?)%% більше шкоди оглушеним, скутим, сповільненим ворогам або тим, хто тікає%.$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^Поглинає наступні ([%-%d%.,]+%%?) шкоди, ([%-%d%.,]+%%?)%% макс%. здоров'я%. Застосовується знову, коли щит розіб'ється%.$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^Критичний удар вкидає вас у шквал: перезарядки відновлюються на ([%-%d%.,]+%%?)%% швидше протягом 5 с%.$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^Ваші святі критичні удари лікують вас на ([%-%d%.,]+%%?)%% макс%. здоров'я, не частіше разу на секунду%.$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^Повертає вас до життя з половиною здоров'я, коли ви гинете%. Вміщує не більше ([%-%d%.,]+%%?) життів%.$", "Returns you to life at half health when you die. Holds {n} lives at most.", { "n" } },
			{ "^Клас «(.-)» отримує ([%-%d%.,]+%%?) досвіду талантів: 1 нове очко таланту! Розподіліть його в зброярні%.$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^Клас «(.-)» отримує ([%-%d%.,]+%%?) досвіду талантів: нових очок таланту — ([%-%d%.,]+%%?)! Розподіліть їх у зброярні%.$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^«Бойовий клич» та інші ваші посилення шкоди, швидкості, щита і шипів на ([%-%d%.,]+%%?)%% сильніші%.$", "Battle Shout and your other damage, haste, shield and thorns buffs are {v}% stronger.", { "v" } },
			{ "^Віха%. Ваші критичні удари змушують ціль стікати кров'ю на ([%-%d%.,]+%%?)%% від удару протягом 6 с%.$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^Зверхність: кожні 12 с ваші вищі демони посилюють свою наступну атаку на %+([%-%d%.,]+%%?)%% шкоди%.$", "Supremacy: every 12 sec, your greater demons empower their next attack for +{v}% damage.", { "v" } },
			{ "^Коли ворог б'є вас у ближньому бою, ([%-%d%.,]+%%?)%% шансу застосувати безплатне «Чіпке коріння»%.$", "When an enemy strikes you in melee, {v}% chance to cast a free Entangling Roots.", { "v" } },
			{ "^Лікує вас на ([%-%d%.,]+%%?), ([%-%d%.,]+%%?)%% макс%. здоров'я, ([%-%d%.,]+%%?)%. Застосовується, коли здоров'я падає нижче 85%%%.$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "amount", "share", "over" } },
			{ "^Захищає вас від ([%-%d%.,]+%%?) шкоди за кожного враженого ворога, до ([%-%d%.,]+%%?), доки щит не розіб'ється%.$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^Зниження шкоди понад межу не марнується: кожен його 1%% стає на ([%-%d%.,]+%%?)%% більшою шкодою%.$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^Віха%. «Блискавка» і «Ланцюгова блискавка» мають ([%-%d%.,]+%%?)%% шансу безплатно вдарити знову%.$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^Віха%. Ваші вогняні критичні удари підпалюють ціль на ([%-%d%.,]+%%?)%% від удару протягом 4 с%.$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^Ваші закляття періодичної шкоди тепер накопичуються ([%-%d%.,]+%%?) разів на одному ворогові%.$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^Збільшує всю завдану вами шкоду на ([%-%d%.,]+%%?)%% за кожні 10%% зниження шкоди, що у вас є%.$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^Зверхність: ваш вартовий загибелі завдає на ([%-%d%.,]+%%?)%% більше шкоди босам і елітним%.$", "Supremacy: your Doomguard deals {v}% more damage to bosses and elites.", { "v" } },
			{ "^Перезарядки «Контузивного пострілу» і «Прицільного пострілу» на ([%-%d%.,]+%%?)%% коротші%.$", "Concussive Shot and Aimed Shot cooldowns are {v}% shorter.", { "v" } },
			{ "^«Вогняна нова», «Тотем магми» і «Вогняний шок» завдають на ([%-%d%.,]+%%?)%% більше шкоди%.$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^Зверхність: «Пекельне полум'я» вашого інфернала завдає на ([%-%d%.,]+%%?)%% більше шкоди%.$", "Supremacy: your Infernal's Hellfire deals {v}% more damage.", { "v" } },
			{ "^«Тотем магми» сягає на ([%-%d%.,]+%%?)%% далі, а «Пекучий тотем» стріляє в більше цілей%.$", "Magma Totem reaches {v}% farther and Searing Totem fires at more targets.", { "v" } },
			{ "^«Молот правосуддя» завдає на ([%-%d%.,]+%%?)%% більше шкоди і швидше перезаряджається%.$", "Hammer of Justice deals {v}% more damage and recovers faster.", { "v" } },
			{ "^Ви завдаєте на ([%-%d%.,]+%%?)%% більше шкоди за кожні 10%% зниження шкоди, що у вас є%.$", "You deal {v}% more damage for every 10% damage reduction you have.", { "v" } },
			{ "^Віха%. Ваші тіньові закляття також б'ють ціль на ([%-%d%.,]+%%?)%% її макс%. здоров'я%.$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^Кожен імпульс «Освячення» завдає додатково ([%-%d%.,]+%%?)%% вашого макс%. здоров'я%.$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
			{ "^Протягом ([%-%d%.,]+%%?) с вороги, що б'ють вас у ближньому бою, отримують ([%-%d%.,]+%%?) шкоди%.(.-)$", "For {dur} sec, enemies that hit you in melee take {n} damage.{in_fight}", { "dur", "n", "in_fight" } },
			{ "^([%-%d%.,]+%%?) Починає з «(.-)»; кожен рівень пропонує три його закляття%. Здоров'я: ([%-%d%.,]+%%?)%.$", "{blurb} Starts with {spell}; every level offers three of its spells. {hp} health.", { "blurb", "spell", "hp" } },
			{ "^Нападники в ближньому бою отримують ([%-%d%.,]+%%?) шкоди, яку вони вам завдають%.$", "Melee attackers take {p} of the damage they deal you.", { "p" } },
			{ "^([%-%d%.,]+%%?)%% шкоди, яку вороги завдають вам у ближньому бою, повертається їм%.$", "{v}% of the damage enemies deal you in melee is dealt back to them.", { "v" } },
			{ "^Чародійні закляття і закляття природи завдають на ([%-%d%.,]+%%?)%% більше шкоди%.$", "Arcane and Nature spells deal {v}% more damage.", { "v" } },
			{ "^Перезарядки «Кільця смерті» і «Висмоктування життя» на ([%-%d%.,]+%%?)%% коротші%.$", "Death Coil and Drain Life cooldowns are {v}% shorter.", { "v" } },
			{ "^Вороги, вбиті вами під час «(.-)», вибухають на ([%-%d%.,]+%%?) свого макс%. здоров'я$", "Enemies you kill during {spell} explode for {frac} of their max health", { "spell", "frac" } },
			{ "^Ви завдаєте на ([%-%d%.,]+%%?)%% більше шкоди ворогам, у яких менше 30%% здоров'я%.$", "You deal {v}% more damage to enemies below 30% health.", { "v" } },
			{ "^«Удар щитом» завдає на ([%-%d%.,]+%%?)%% більше шкоди і швидше перезаряджається%.$", "Shield Slam deals {v}% more damage and recovers faster.", { "v" } },
			{ "^«Вогняний стовп» і «Вибухова хвиля» завдають на ([%-%d%.,]+%%?)%% більше шкоди%.$", "Flamestrike and Blast Wave deal {v}% more damage.", { "v" } },
			{ "^Збільшує всю шкоду та шанс критичного удару ваших демонів на ([%-%d%.,]+%%?)%%%.$", "Increases all damage and your demons' critical strike chance by {v}%.", { "v" } },
			{ "^«Пекучий біль» і «Жертовне полум'я» завдають на ([%-%d%.,]+%%?)%% більше шкоди%.$", "Searing Pain and Immolate deal {v}% more damage.", { "v" } },
			{ "^Щит від «Удару щитом» тримає на ([%-%d%.,]+%%?)%% більше вашого макс%. здоров'я%.$", "Shield Slam's shield holds {v}% more of your maximum health.", { "v" } },
