		lines = {
			{ "^里程碑。每次冒险开始时你就拥有神圣震击，它的每一道光束都会跳向另外2个敌人，造成([%-%d%.,]+%%?)%%的效果。$", "Milestone. You start every run with Holy Shock, and each of its bolts leaps to 2 more enemies for {v}% of it.", { "v" } },
			{ "^里程碑。你施放的每次治疗还会对12码内的所有敌人造成相当于治疗量([%-%d%.,]+%%?)%%的自然伤害。$", "Milestone. Every heal you cast also strikes every enemy within 12 yd for {v}% of the healing as Nature damage.", { "v" } },
			{ "^里程碑。惩击和神圣之火的暴击会点燃目标，在6秒内造成相当于该次攻击([%-%d%.,]+%%?)%%的伤害。$", "Milestone. Smite and Holy Fire critical strikes set their target alight for {v}% of the hit over 6 sec.", { "v" } },
			{ "^你的持续伤害法术跳动速度加快([%-%d%.,]+%%?)%%：同样时间内跳动更多次，造成更多伤害。最多([%-%d%.,]+%%?)%%。$", "Your damage over time spells tick {v}% faster: more ticks, and more damage, in the same time. {max}% at most.", { "v", "max" } },
			{ "^里程碑。自动射击可以穿透：每支箭还会打击目标后方的1个敌人，造成([%-%d%.,]+%%?)%%的效果。$", "Milestone. Auto Shot pierces: every arrow also strikes 1 enemy beyond its target for {v}% of it.", { "v" } },
			{ "^里程碑。你的暴击撕开目标：目标流血，在6秒内受到相当于该次攻击([%-%d%.,]+%%?)%%的伤害。$", "Milestone. Your critical strikes rip the target open: it bleeds for {v}% of the hit over 6 sec.", { "v" } },
			{ "^里程碑。你的陷阱会困住命中的敌人：陷阱每次命中有([%-%d%.,]+%%?)%%的几率使敌人定身2秒。$", "Milestone. Your traps hold what they hit: every hit of a trap has a {v}% chance to root the enemy for 2 sec.", { "v" } },
			{ "^死亡缠绕会立即对目标造成你的吸取生命剩余伤害的([%-%d%.,]+%%?)%%，且不会消耗吸取生命。$", "Death Coil instantly deals {v}% of your Drain Life's remaining damage on its target, without consuming it.", { "v" } },
			{ "^里程碑。你的暗影法术还会对被击中的目标造成相当于其最大生命值([%-%d%.,]+%%?)%%的伤害。$", "Milestone. Your Shadow spells also strike what they hit for {v}% of its maximum health.", { "v" } },
			{ "^里程碑。你的火焰暴击会点燃目标，在4秒内造成相当于该次攻击([%-%d%.,]+%%?)%%的伤害。$", "Milestone. Your Fire critical strikes ignite the target for {v}% of the hit over 4 sec.", { "v" } },
			{ "^你的恶魔的攻击有([%-%d%.,]+%%?)%%的几率产生全额伤害的回响。这是它们唯一的回响来源。$", "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", { "v" } },
			{ "^里程碑。寒冰箭命中时会碎裂：对目标5码内的所有敌人造成其伤害的([%-%d%.,]+%%?)%%。$", "Milestone. Frostbolt splinters on impact: {v}% of its damage to every enemy within 5 yd of its target.", { "v" } },
			{ "^每命中一个敌人，为你提供可吸收([%-%d%.,]+%%?)点伤害的护盾，最多([%-%d%.,]+%%?)点，直到护盾破碎。$", "Shields you against {n} damage for every enemy hit, up to {max}, until it breaks.", { "n", "max" } },
			{ "^你对受你的持续伤害效果（如撕裂和重伤）影响的敌人造成的伤害提高([%-%d%.,]+%%?)%%。$", "You deal {v}% more damage to enemies suffering your damage-over-time effects, such as Rend and Deep Wounds.", { "v" } },
			{ "^吸收你受到的接下来([%-%d%.,]+%%?)点伤害，即最大生命值的([%-%d%.,]+%%?)%%。护盾破碎后再次施放。$", "Absorbs the next {amount} damage you take, {share}% of your max health. Cast again once the shield breaks.", { "amount", "share" } },
			{ "^里程碑。你的暴击使目标流血，在6秒内受到相当于该次攻击([%-%d%.,]+%%?)%%的伤害。$", "Milestone. Your critical strikes make the target bleed for {v}% of the hit over 6 sec.", { "v" } },
			{ "^里程碑。你的暴击有([%-%d%.,]+%%?)%%的几率掷出一次免费的驱邪术，每秒最多一次。$", "Milestone. Your critical strikes have a {v}% chance to hurl a free Exorcism, at most once a second.", { "v" } },
			{ "^你的神圣暴击会为你恢复相当于最大生命值([%-%d%.,]+%%?)%%的生命，每秒最多一次。$", "Your Holy critical strikes heal you for {v}% of your maximum health, at most once a second.", { "v" } },
			{ "^([%-%d%.,]+%%?)为你恢复([%-%d%.,]+%%?)点生命值，即最大生命值的([%-%d%.,]+%%?)%%。生命值低于85%%时施放。$", "Heals you for {amount}, {share}% of your max health, {over}. Cast when you fall below 85% health.", { "over", "amount", "share" } },
			{ "^至尊：每12秒，你的高阶恶魔的下一次攻击获得强化，伤害%+([%-%d%.,]+%%?)%%。$", "Supremacy: every 12 sec, your greater demons empower their next attack for +{v}% damage.", { "v" } },
			{ "^战斗怒吼和你的其他伤害、急速、护盾和荆棘增益效果增强([%-%d%.,]+%%?)%%。$", "Battle Shout and your other damage, haste, shield and thorns buffs are {v}% stronger.", { "v" } },
			{ "^超过上限的伤害减免不会浪费：每1%%转化为([%-%d%.,]+%%?)%%的伤害提高。$", "Damage reduction past the cap is not wasted: each 1% of it becomes {v}% more damage.", { "v" } },
			{ "^敌人用近战攻击你时，有([%-%d%.,]+%%?)%%的几率施放一次免费的纠缠根须。$", "When an enemy strikes you in melee, {v}% chance to cast a free Entangling Roots.", { "v" } },
			{ "^你施放的每个法术额外造成相当于你最大生命值([%-%d%.,]+%%?)%%的伤害。$", "Every spell you cast deals an extra {v}% of your maximum health.", { "v" } },
			{ "^你对被冻结、击晕、减速或逃跑的敌人造成的伤害提高([%-%d%.,]+%%?)%%。$", "You deal {v}% more damage to frozen, stunned, slowed or fleeing enemies.", { "v" } },
			{ "^你对被击晕、定身、减速或逃跑的敌人造成的伤害提高([%-%d%.,]+%%?)%%。$", "You deal {v}% more damage to stunned, rooted, slowed or fleeing enemies.", { "v" } },
			{ "^你的(.-)获得了([%-%d%.,]+%%?)点天赋经验：1个新天赋点！去军械库分配吧。$", "Your {class}s earn {xp} talent experience: 1 new talent point! Spend it in the armory.", { "class", "xp" } },
			{ "^([%-%d%.,]+%%?) 初始法术为(.-)；每次升级提供三个该职业的法术。([%-%d%.,]+%%?)生命值。$", "{blurb} Starts with {spell}; every level offers three of its spells. {hp} health.", { "blurb", "spell", "hp" } },
			{ "^暴击会让你进入乱舞状态：5秒内冷却恢复速度加快([%-%d%.,]+%%?)%%。$", "A critical strike sends you into a flurry: cooldowns recover {v}% faster for 5 sec.", { "v" } },
			{ "^在你的奉献中燃烧的敌人在3秒内受到你的伤害提高([%-%d%.,]+%%?)%%。$", "Enemies burning in your Consecration take {v}% more damage from you for 3 sec.", { "v" } },
			{ "^使你免疫所有伤害，持续([%-%d%.,]+%%?)秒。生命值低于35%%时施放。$", "Makes you immune to all damage for {dur} sec. Cast when you fall below 35% health.", { "dur" } },
			{ "^盾牌猛击的护盾额外吸收相当于你最大生命值([%-%d%.,]+%%?)%%的伤害。$", "Shield Slam's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^你的(.-)获得了([%-%d%.,]+%%?)点天赋经验：([%-%d%.,]+%%?)个新天赋点！去军械库分配吧。$", "Your {class}s earn {xp} talent experience: {n} new talent points! Spend them in the armory.", { "class", "xp", "n" } },
			{ "^破碎的护盾会爆发，对([%-%d%.,]+%%?)码内的敌人造成其吸收量([%-%d%.,]+%%?)的伤害$", "A broken shield bursts for {frac} of what it absorbed on enemies within {radius} yd", { "radius", "frac" } },
			{ "^被挫志怒吼击中的敌人在6秒内受到你的伤害提高([%-%d%.,]+%%?)%%。$", "Enemies hit by Demoralizing Shout take {v}% more damage from you for 6 sec.", { "v" } },
			{ "^奉献的每一跳额外造成相当于你最大生命值([%-%d%.,]+%%?)%%的伤害。$", "Every tick of Consecration deals an extra {v}% of your maximum health.", { "v" } },
			{ "^里程碑。闪电箭和闪电链有([%-%d%.,]+%%?)%%的几率免费再打击一次。$", "Milestone. Lightning Bolt and Chain Lightning have a {v}% chance to strike again for free.", { "v" } },
			{ "^至尊：你的末日守卫对首领和精英造成的伤害提高([%-%d%.,]+%%?)%%。$", "Supremacy: your Doomguard deals {v}% more damage to bosses and elites.", { "v" } },
			{ "^你的暗影法术有([%-%d%.,]+%%?)%%的几率使命中的目标昏迷1%.5秒。$", "Your Shadow spells have a {v}% chance to stun what they hit for 1.5 sec.", { "v" } },
			{ "^奉献的护盾额外吸收相当于你最大生命值([%-%d%.,]+%%?)%%的伤害。$", "Consecration's shield holds {v}% more of your maximum health.", { "v" } },
			{ "^火焰新星、熔岩图腾和烈焰震击造成的伤害提高([%-%d%.,]+%%?)%%。$", "Fire Nova, Magma Totem and Flame Shock deal {v}% more damage.", { "v" } },
			{ "^你每拥有10%%伤害减免，造成的所有伤害提高([%-%d%.,]+%%?)%%。$", "Increases all damage you deal by {v}% for every 10% damage reduction you have.", { "v" } },
			{ "^冷却时间在免疫结束时开始计算：每次施放间隔([%-%d%.,]+%%?)秒。$", "Its cooldown starts when the immunity ends: {total} sec from one cast to the next.", { "total" } },
			{ "^你的持续伤害法术现在可以在一个敌人身上叠加([%-%d%.,]+%%?)次。$", "Your damage over time spells now stack {n} times on one enemy.", { "n" } },
			{ "^身中(.-)死亡的敌人会爆炸，造成其最大生命值([%-%d%.,]+%%?)的伤害$", "Enemies that die with {spell} on them explode for {frac} of their max health", { "spell", "frac" } },
